 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    line = max((v for v in counts if v != background), key=lambda v: counts[v])

    row_lines = [r for r in range(h)
                 if sum(v == line for v in grid[r]) >= 0.70 * w]
    col_lines = [c for c in range(w)
                 if sum(grid[r][c] == line for r in range(h)) >= 0.70 * h]

    def has_marker_on_row(r):
        return any(grid[r][c] not in (background, line) for c in col_lines)

    def has_marker_on_col(c):
        return any(grid[r][c] not in (background, line) for r in row_lines)

    marked_rows = [r for r in row_lines if has_marker_on_row(r)]
    marked_cols = [c for c in col_lines if has_marker_on_col(c)]
    rows = [r for r in row_lines if marked_rows[0] <= r <= marked_rows[-1]]
    cols = [c for c in col_lines if marked_cols[0] <= c <= marked_cols[-1]]

    out = []
    for r0, r1 in zip(rows, rows[1:]):
        out_row = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1],
                       grid[r1][c0], grid[r1][c1]]
            out_row.append(corners[0] if all(v == corners[0] for v in corners)
                           else background)
        out.append(out_row)
    return out
